SELECT
  DATE_FORMAT(minute_time, '%Y-%m-%d %H:%i') AS time,
  ROUND(SUM(IFNULL(point_value, 0)), 2) AS value
FROM iot_telemetry_minute
WHERE aggregator_id = #{aggregatorId}
  AND point_code = #{pointCode}
  AND minute_time  >=  #{startTime}
  AND minute_time  <=  #{endTime}


      AND (
        device_id IN

          #{deviceId}

        OR device_code IN

          #{deviceCode}

      )


      AND device_id IN

        #{deviceId}



      AND device_code IN

        #{deviceCode}



      AND 1 = 0


GROUP BY minute_time
ORDER BY minute_time
